let molds=[];let num=2e3;let d;let width1,height1;function setup(){const container=document.getElementById("canvas-container");const containerWidth=container.offsetWidth;const containerHeight=container.offsetHeight;let canvas=createCanvas(containerWidth,containerHeight);canvas.parent("canvas-container");angleMode(DEGREES);d=pixelDensity();width1=width;height1=height;for(let i=0;i<num;i++){molds[i]=new Mold}}function draw(){background(0,5);loadPixels();for(let i=0;i<num;i++){molds[i].update();molds[i].display()}}function windowResized(){const container=document.getElementById("canvas-container");const newWidth=container.offsetWidth;const newHeight=container.offsetHeight;resizeCanvas(newWidth,newHeight);const widthRatio=newWidth/width;const heightRatio=newHeight/height;width1=newWidth;height1=newHeight;for(let i=0;i<num;i++){molds[i].x*=widthRatio;molds[i].y*=heightRatio}}class Mold{constructor(){this.x=random(width/2-20,width/2+20);this.y=random(height/2-20,height/2+20);this.r=.5;this.heading=random(360);this.vx=cos(this.heading);this.vy=sin(this.heading);this.rotAngle=45;this.rSensorPos=createVector(0,0);this.lSensorPos=createVector(0,0);this.fSensorPos=createVector(0,0);this.sensorAngle=45;this.sensorDist=10}update(){this.vx=cos(this.heading);this.vy=sin(this.heading);this.x=(this.x+this.vx+width1)%width1;this.y=(this.y+this.vy+height1)%height1;this.getSensorPos(this.rSensorPos,this.heading+this.sensorAngle);this.getSensorPos(this.lSensorPos,this.heading-this.sensorAngle);this.getSensorPos(this.fSensorPos,this.heading);let index,l,r,f;index=4*(d*floor(this.rSensorPos.y))*(d*width1)+4*(d*floor(this.rSensorPos.x));r=pixels[index];index=4*(d*floor(this.lSensorPos.y))*(d*width1)+4*(d*floor(this.lSensorPos.x));l=pixels[index];index=4*(d*floor(this.fSensorPos.y))*(d*width1)+4*(d*floor(this.fSensorPos.x));f=pixels[index];if(f>l&&f>r){this.heading+=0}else if(f<l&&f<r){if(random(1)<.5){this.heading+=this.rotAngle}else{this.heading-=this.rotAngle}}else if(l>r){this.heading+=-this.rotAngle}else if(r>l){this.heading+=this.rotAngle}}display(){noStroke();fill(255);ellipse(this.x,this.y,this.r*2,this.r*2)}getSensorPos(sensor,angle){sensor.x=(this.x+this.sensorDist*cos(angle)+width1)%width1;sensor.y=(this.y+this.sensorDist*sin(angle)+height1)%height1}}document.addEventListener("DOMContentLoaded",()=>{const navMapping={"nav-home":"main-text-home","nav-about":"main-text-about","nav-projects":"main-text-projects","nav-inspiration":"main-text-inspiration","nav-contact":"main-text-contact"};const navItems=document.querySelectorAll(".nav-container a");const updateNavStyles=activeNavClass=>{navItems.forEach(navItem=>{if(navItem.classList.contains(activeNavClass)){navItem.classList.add("active-nav");navItem.classList.remove("inactive-nav")}else{navItem.classList.add("inactive-nav");navItem.classList.remove("active-nav")}})};navItems.forEach(navItem=>{navItem.addEventListener("click",()=>{const targetId=navMapping[navItem.classList[0]];if(targetId){Object.values(navMapping).forEach(id=>{const section=document.getElementById(id);if(section){section.style.display="none"}});const targetSection=document.getElementById(targetId);if(targetSection){targetSection.style.display="block"}updateNavStyles(navItem.classList[0])}})});const defaultNavClass="nav-home";document.querySelector(`.${defaultNavClass}`).click()});function switchMode(mode){const url=new URL(window.location);url.searchParams.set("mode",mode);window.location.href=url.toString()}document.addEventListener("DOMContentLoaded",function(){const urlParams=new URLSearchParams(window.location.search);const mode=urlParams.get("mode");const modeSwitchers=document.querySelectorAll(".mode-switcher");if(modeSwitchers.length>=2){if(mode==="white"){modeSwitchers[0].textContent="white [#]";modeSwitchers[1].textContent="dark [ ]"}else{modeSwitchers[0].textContent="white [ ]";modeSwitchers[1].textContent="dark [#]"}}if(mode==="white"){document.querySelectorAll(".main-text, .main-title, .under-title, .nav-container a").forEach(el=>{el.style.color="black"});document.querySelectorAll(".text-shadow").forEach(el=>{el.style.textShadow="0 0 5px #000000"});document.querySelectorAll(".canvas-container").forEach(el=>{el.style.borderColor="black"});if(window.innerWidth>768){document.querySelectorAll(".vertical-link a, .vertical-legacy-page a").forEach(el=>{el.style.color="#ffffff"})}const defaultScript=document.querySelector('script[src="./scripts/script.js"]');if(defaultScript){defaultScript.remove()}const legacyScript=document.createElement("script");legacyScript.src="./legacy/script.js";document.body.appendChild(legacyScript)}});